        "text": "Some teams may rarely or always exhibit full coverage, reducing usable within-team variation."
      },
      {
        "code": "LEAKAGE_LOOKAHEAD",
        "text": "If roles are derived from the same season's data, there is lookahead bias; only prior-season or rolling historical data should be used."
      },
      {
        "code": "MULTIPLE_TESTING",
        "text": "If testing multiple seasons or secondary outcomes (net rating, playoff performance), corrections are needed."
      }
    ],
    "predicted_outcome": {
      "supported": 0.25,
      "rejected": 0.30,
      "untestable": 0.35,
      "artifact": 0.05,
      "uncertain": 0.05
    },
    "decision": "proceed_with_changes",
